import pandas as pd


def solve(data):
    ban = pd.read_csv('coffee-sales-cc0.csv')
    gio = pd.to_datetime(ban['datetime']).dt.hour
    dem = gio[ban['coffee_name'] == data['mon']].value_counts()
    dinh = int(dem.max())
    return {'gio': sorted(int(g) for g in dem[dem == dinh].index),
            'so_luot': dinh}
